local E = require "ejoysdk_lua.ejoysdk"
local G = require "ejoysdk_lua.ejoysdk_gangplank"
local Vendor = require "ejoysdk_lua.vendors.vendor"
local EM = require "ejoysdk_lua.ejoysdk_module"

local CHANNEL = "SENTRY"
local M = Vendor:Inherit(CHANNEL)

local infoTableMap = {} --批量上传日志用的
local infoTableArray = {} --批量上传日志用，每一个元素是单条的日志，放在上述map的一个节点下

local TAG = EM.MODULE.SENTRY .. "log_upload"

local configTable = {}
local logUrlTable = {
    single="https://log-forward.ejoy.com/v1/log", --单条info日志url的默认域名
    multi="https://log-forward.ejoy.com/v1/logs" --批量info日志url的默认域名
}
local defautConfigTable = {
    appid="", --Sentry后台创建项目后的唯一标识
    secret="",
    product="", --s3/f2/mcd这些代号
    log_info_limit=20, --info日志的保存条数，满了后才上传
}

function M.init(config, cb)
    assert(config)
    assert( type(config.appid)=="string" and #(config.appid) ~= 0)
    assert( type(config.secret)=="string" and #(config.secret) ~= 0)

    configTable = config or defautConfigTable
    if config and (not config.log_info_limit) then
        configTable.log_info_limit = defautConfigTable.log_info_limit --游戏不传日志限额，则使用默认值
    end
    if config and type(config.log_url_domain)=="string" and #(config.log_url_domain) ~= 0 then
        -- string.gsub => 会对游戏传进来的domain做首尾空格的去除
        local domain = string.gsub(config.log_url_domain, "^[%s]*(.-)[%s]*$", "%1")
        logUrlTable.single = "https://"..domain.."/v1/log"
        logUrlTable.multi = "https://"..domain.."/v1/logs"
    end
    cb(true)
end

--加签的顺序
local sign_src = {"account", "environment", "level", "msg", "os", "product", "role", "server", "timestamp", "ver"}

local function setup_http_params(level, msg, tags, extra_params)
    local info = {}
    local userInfo = G.user_info()
    local uid = "nil" --未登录时，用nil上报，方便后台检索
    if userInfo then
        uid = userInfo.uid  -- 登录前userInfo.uid是nil
    end

    info.account = uid or 'nil'  --G.user_info().uid
    info.environment = E.CONFIG.get_config('product')
    info.level = level or ' '  --因为该字段要用于加签，所以至少也要有个空格
    info.msg = msg or ' '
    info.os = _ejoysdk.os()
    -- 保留product_code是为了兼容旧版本，已接入的游戏不用修改
    info.product = configTable.product or configTable.product_code



    local playerInfo = G.player_info()
    local roleId = 'nil' --未登录时，用nil上报，方便后台检索
    local serverId = 'nil' --未登录时，用nil上报，方便后台检索

    if playerInfo  then
        roleId = playerInfo.player_id --角色id
        serverId = playerInfo.server_id --服务器server id
    end

    info.role = roleId
    info.server = serverId

    info.timestamp = tostring(os.time()) -- os.time()
    local tempVersion = E.Sysinfo:app_version_name() --版本号，对应iOS里的short version
    if( type(tempVersion)=="string" and #(tempVersion) ~= 0 ) then
        info.ver = tempVersion
    else 
        info.ver = "0"
    end

    local utdid = E.Sysinfo.utdid()
    local utdidValid = utdid and type(utdid)=="string" and #(utdid) ~= 0

    --未登录用户，上报日志，后台可根据utdid筛查, utdid放在tags里面
    --SDK侧，只有在游戏没往tags里放utdid，且SDK能正常取到utdid时，才往里插utdid字段
    local tagsInfo = tags or {}
    if (not tagsInfo.utdid) and utdidValid then
        tagsInfo.utdid = utdid
    end

    info.tags = tagsInfo
    info.ext = extra_params
    info.appid = configTable.appid --E.CONFIG.get_config("appid") --这个是游戏设置的，必须要设置

    assert(info.environment)
    assert(info.product)
    assert(info.role)
    assert(info.server)

    return info
end


local function sign_logs(info)
    info = info or {}
    local secret = configTable.secret --E.CONFIG.get_config("secret")
    local sign_str = ""
    for _, sign_node in ipairs(sign_src) do
        sign_str = sign_str .. sign_node .. (info[sign_node] or " ")
    end
    sign_str = sign_str .. "\n" .. secret

    --_ejoysdk.log('sign_str = '.. sign_str)

    local value =  _ejoysdk_crypt.hmac_sha1(secret, sign_str)
    local resultBase64 = _ejoysdk_crypt.base64encode(value)

    info.sign = resultBase64
end


local function send_log_to_sentry_server(params, url)
    E.LOG.debug(TAG, 'sentry------http - start')
    url = url or logUrlTable.single
    --TODO:gzip压缩数据native还不支持
    -- local headMap = {} --{["Accept-Encoding"]="gzip",["Content-Encoding"]="gzip",["Content-Type"]="application/gzip"}
    --headers = headMap

    E.HTTP.post(url, { trace =true, acceptable=E.HTTP.CT_JSON }, E.HTTP.CT_JSON, params, function(resp)
        E.LOG.debug(TAG,'sentry------http - end')
        if resp.status == 200 then
            E.LOG.debug(TAG, ' log upload success')
        else
            E.LOG.debug(TAG, ' http error, resp.status = '.. tostring(resp.status))
        end
    end)
end

function M.sentry_log_error_event(msg, tags, extra_params)
    local info = setup_http_params('Error', msg, tags, extra_params);
    sign_logs(info)
    send_log_to_sentry_server(info)
end

function M.sentry_log_warning_event(msg, tags, extra_params)
    local info = setup_http_params('Warning', msg, tags, extra_params);
    sign_logs(info)
    send_log_to_sentry_server(info)
end

function M.sentry_log_info_event(msg, tags, extra_params)

    if #infoTableArray == 0 then
        --每条日志都会有的公共信息，存入infoTableMap里记录，仅用于批量上传
        infoTableMap = setup_http_params()
        sign_logs(infoTableMap)
    end

    --每条日志的特有信息
    local info = {}
    info.ext = extra_params --setup_http_params('Info', msg, tags, extra_params);
    info.level = "Info"
    info.msg = msg
    info.tags = tags
    info.timestamp = tostring(os.time()) -- os.time()

    --装载到table里以数组形式存放，等满了再一起上传
    local length = #infoTableArray
    table.insert(infoTableArray, info) --追加到数组里

    local tableLimit = configTable.log_info_limit
    if length+1 >= tableLimit then
        --当table达到数量限制的时候，则一次性进行上传，同时清空table
        M.sentry_log_info_sent_all_cache()
    end

