    --    end
    --end
end

--触发发送所有已缓存的日志
function M.sentry_log_info_sent_all_cache()
    if #infoTableArray == 0 then
        return
    end

    infoTableMap.logs = infoTableArray --节点拼接
    send_log_to_sentry_server(infoTableMap, logUrlTable.multi)

    infoTableMap = {} -- 清空数据
    infoTableArray = {}
end


return M